// Composed from the shadcn/ui Typography documentation (MIT).
import * as React from "react";
import { cn } from "./utils";
import "./typography.css";
export function Typography({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return <div className={cn("roc-ui roc-typography", className)} {...props} />;
}
export function TypographyH1(props: React.ComponentProps<"h1">) {
  return <h1 {...props} />;
}
export function TypographyH2(props: React.ComponentProps<"h2">) {
  return <h2 {...props} />;
}
export function TypographyH3(props: React.ComponentProps<"h3">) {
  return <h3 {...props} />;
}
export function TypographyP(props: React.ComponentProps<"p">) {
  return <p {...props} />;
}
export function TypographyBlockquote(
  props: React.ComponentProps<"blockquote">,
) {
  return <blockquote {...props} />;
}
export function TypographyCode(props: React.ComponentProps<"code">) {
  return <code {...props} />;
}
export function TypographyMuted({
  className,
  ...props
}: React.ComponentProps<"p">) {
  return <p className={cn("roc-typography-muted", className)} {...props} />;
}

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-typography {
  line-height: 1.7;
  overflow-wrap: anywhere;
}
.roc-typography h1 {
  font-size: clamp(28px, 5vw, 40px);
  line-height: 1.12;
  letter-spacing: -0.035em;
  margin: 0 0 20px;
  font-weight: 600;
}
.roc-typography h2 {
  font-size: 24px;
  line-height: 1.2;
  letter-spacing: -0.025em;
  margin: 24px 0 12px;
  font-weight: 600;
}
.roc-typography h3 {
  font-size: 18px;
  margin: 20px 0 10px;
  font-weight: 600;
}
.roc-typography p {
  margin: 0 0 12px;
}
.roc-typography blockquote {
  border-inline-start: 2px solid #ddd;
  padding-inline-start: 16px;
  margin: 20px 0;
  font-style: italic;
}
.roc-typography code {
  font-family: ui-monospace, monospace;
  background: #f4f4f4;
  border-radius: max(0px, calc(var(--roc-radius, 9px) - 5px));
  padding: 2px 5px;
  font-size: 0.9em;
}
.roc-typography-muted {
  color: var(--roc-muted, #777);
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
